import { RefObject } from 'react';

export function getDraggableBounds(
  elementRef: RefObject<HTMLDivElement>,
  boundRef: RefObject<HTMLDivElement>,
) {
  const { clientWidth: boundaryWidth, clientHeight: boundaryHeight } =
    boundRef.current ?? {
      clientWidth: 0,
      clientHeight: 0,
    };

  const { clientWidth: elementWidth, clientHeight: elementHeight } =
    elementRef.current ?? {
      clientWidth: 0,
      clientHeight: 0,
    };

  const maxRightBoundary = boundaryWidth - elementWidth;
  const maxTopBoundary = boundaryHeight - elementHeight;

  return {
    right: maxRightBoundary,
    top: maxTopBoundary,
  };
}
